{{(() => {
  const en = appsmith.store.bo_lang === 'en';
  const s = String(GetOrderDetails.data[0]?.status || '');
  const bg = { created: '🟡 Чака куриер', dispatched: '🔵 Възложена', started: '🚚 В път', enroute: '🚚 В път', in_transit: '🚚 В път',
    delivery_attempted: '🟠 2-ри опит', returning: '↩️ Връща се', order_returned: '↩️ Върната', delivered: '✅ Доставена', order_delivered: '✅ Доставена',
    completed: '✅ Доставена', canceled: '❌ Отказана', cancelled: '❌ Отказана', order_cancel: '❌ Отказана' };
  const eng = { created: '🟡 Awaiting courier', dispatched: '🔵 Dispatched', started: '🚚 In transit', enroute: '🚚 In transit', in_transit: '🚚 In transit',
    delivery_attempted: '🟠 2nd attempt', returning: '↩️ Returning', order_returned: '↩️ Returned', delivered: '✅ Delivered', order_delivered: '✅ Delivered',
    completed: '✅ Delivered', canceled: '❌ Cancelled', cancelled: '❌ Cancelled', order_cancel: '❌ Cancelled' };
  const word = ((en ? eng : bg)[s] || s).replace(/^\S+\s/, '');
  return (en ? 'Status: ' : 'Статус: ') + word;
})()}}
